var business = ($input.first().json.business_name || "Business").toString();
var base = business.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 40) || "business";
var suffix = Math.random().toString(36).slice(2, 7);
var slug = base + "-" + suffix;
var staffEmail = "owner-" + suffix + "@demo.automationgini.com";
var staffPassword = "Demo" + Math.floor(1000 + Math.random() * 9000) + "!";
var leadId = $("Normalize Input").item.json.lead_id;
var tenantId = $("Normalize Input").item.json.tenant_id;
var agentId = $("Normalize Input").item.json.agent_id;
return [{ json: { lead_id: leadId, tenant_id: tenantId, agent_id: agentId, business_name: business, slug: slug, staff_email: staffEmail, staff_password: staffPassword } }];
